package com.wefyx.support.notification;import org.springframework.stereotype.Service;
@Service public class NotificationService{private final AccountNotificationRepository repository;public NotificationService(AccountNotificationRepository r){repository=r;}public void send(String email,Long requirementId,String type,String title,String message){var n=new AccountNotification();n.setRecipientEmail(email);n.setRequirementId(requirementId);n.setType(type);n.setTitle(title);n.setMessage(message);n.setDeepLinkUrl(requirementId==null?null:"/portal?requirementId="+requirementId);repository.save(n);}}
